,  CONSTRAINT ck_ntf_oacct_state CHECK (verification_state IN ('PENDING', 'VERIFIED', 'SUSPENDED', 'REVOKED')),  CONSTRAINT ck_ntf_oacct_verified CHECK ((verification_state = 'VERIFIED' AND verified_at IS NOT NULL) OR verification_state <> 'VERIFIED'));COMMENT ON TABLE org_ntf_prov_acct_mst IS 'Tenant-owned provider account metadata. Credential references are opaque and actual secret envelopes remain in the approved tenant provider configuration boundary.';COMMENT ON COLUMN org_ntf_prov_acct_mst.id IS 'Stable opaque identity for one tenant-owned provider account.';COMMENT ON COLUMN org_ntf_prov_acct_mst.tenant_org_id IS 'Immutable tenant owner used by RLS and all tenant-safe references.';COMMENT ON COLUMN org_ntf_prov_acct_mst.provider_config_id IS 'Optional existing tenant provider-config record supplying the approved encrypted credential boundary during transition.';COMMENT ON COLUMN org_ntf_prov_acct_mst.provider_code IS 'Provider catalog code owning this tenant account identity.';COMMENT ON COLUMN org_ntf_prov_acct_mst.channel_code IS 'Notification channel supported by this tenant provider account.';COMMENT ON COLUMN org_ntf_prov_acct_mst.account_key IS 'Tenant-managed stable account key.';COMMENT ON COLUMN org_ntf_prov_acct_mst.external_account_id IS 'Provider account identifier scoped to this tenant/provider/channel/environment.';COMMENT ON COLUMN org_ntf_prov_acct_mst.environment_code IS 'Provider environment boundary. TEST and PRODUCTION resources are isolated.';COMMENT ON COLUMN org_ntf_prov_acct_mst.credential_ref IS 'Optional opaque reference to credential configuration; it must never contain credential material.';COMMENT ON COLUMN org_ntf_prov_acct_mst.verification_state IS 'Administrative provider-account verification projection required before activation.';COMMENT ON COLUMN org_ntf_prov_acct_mst.verified_at IS 'UTC time that verification evidence was accepted.';COMMENT ON COLUMN org_ntf_prov_acct_mst.config IS 'Non-secret tenant account configuration v