 org_ntf_prov_acct_mst IS 'Restricts account environments so test resources cannot silently become production resources.';COMMENT ON CONSTRAINT ck_ntf_oacct_state ON org_ntf_prov_acct_mst IS 'Restricts tenant account verification lifecycle to explicit states.';COMMENT ON CONSTRAINT ck_ntf_oacct_verified ON org_ntf_prov_acct_mst IS 'Requires verification timestamp whenever a tenant account is marked VERIFIED.';CREATE INDEX ix_ntf_oacct_tenant ON org_ntf_prov_acct_mst (tenant_org_id, channel_code, is_active);COMMENT ON INDEX ix_ntf_oacct_tenant IS 'Supports tenant-scoped active account selection by notification channel.';ALTER TABLE org_ntf_prov_acct_mst ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_iso_ntf_oacct_read ON org_ntf_prov_acct_mst FOR SELECT USING (tenant_org_id = current_tenant_id());CREATE POLICY tenant_iso_ntf_oacct_write ON org_ntf_prov_acct_mst FOR ALL USING (tenant_org_id = current_tenant_id()) WITH CHECK (tenant_org_id = current_tenant_id());COMMENT ON POLICY tenant_iso_ntf_oacct_read ON org_ntf_prov_acct_mst IS 'Tenant isolation for provider-account reads.';COMMENT ON POLICY tenant_iso_ntf_oacct_write ON org_ntf_prov_acct_mst IS 'Tenant isolation for controlled provider-account administration.';-- Senders are separate because one verified account can own several compatible-- phone numbers, email identities or provider sender IDs.CREATE TABLE sys_ntf_prov_send_mst (  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),  account_id UUID NOT NULL,  channel_code TEXT NOT NULL,  sender_key TEXT NOT NULL,  external_sender_id TEXT NOT NULL,  sender_address TEXT,  sender_kind TEXT NOT NULL,  verification_state TEXT NOT NULL DEFAULT 'PENDING',  verified_at TIMESTAMPTZ,  capabilities JSONB NOT NULL DEFAULT '{}'::jsonb,  name TEXT NOT NULL,  name2 TEXT,  description TEXT,  description2 TEXT,  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by TEXT, created_info TEXT,  updated_at TIMESTAMPTZ, updated_by TEXT, updated_info TEXT,  rec_status SMALLINT NOT NULL 