ntf_osend_tenant IS 'Supports tenant-scoped active sender selection by channel.';ALTER TABLE org_ntf_prov_send_mst ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_iso_ntf_osend_read ON org_ntf_prov_send_mst FOR SELECT USING (tenant_org_id = current_tenant_id());CREATE POLICY tenant_iso_ntf_osend_write ON org_ntf_prov_send_mst FOR ALL USING (tenant_org_id = current_tenant_id()) WITH CHECK (tenant_org_id = current_tenant_id());COMMENT ON POLICY tenant_iso_ntf_osend_read ON org_ntf_prov_send_mst IS 'Tenant isolation for sender reads.';COMMENT ON POLICY tenant_iso_ntf_osend_write ON org_ntf_prov_send_mst IS 'Tenant isolation for controlled sender administration.';-- Platform resources require explicit grants before tenant assignment. Grants-- contain no credential data and do not reveal platform account configuration.CREATE TABLE org_ntf_plat_acct_gr (  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),  tenant_org_id UUID NOT NULL,  platform_account_id UUID NOT NULL,  grant_state TEXT NOT NULL DEFAULT 'ACTIVE',  starts_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),  ends_at TIMESTAMPTZ,  limits JSONB NOT NULL DEFAULT '{}'::jsonb,  grant_version INTEGER NOT NULL DEFAULT 1,  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by TEXT, created_info TEXT,  updated_at TIMESTAMPTZ, updated_by TEXT, updated_info TEXT,  rec_status SMALLINT NOT NULL DEFAULT 1, rec_order INTEGER, rec_notes TEXT,  is_active BOOLEAN NOT NULL DEFAULT true,  CONSTRAINT fk_ntf_pag_tenant FOREIGN KEY (tenant_org_id) REFERENCES org_tenants_mst(id) ON DELETE RESTRICT,  CONSTRAINT fk_ntf_pag_pacct FOREIGN KEY (platform_account_id) REFERENCES sys_ntf_prov_acct_mst(id) ON DELETE RESTRICT,  CONSTRAINT uq_ntf_pacct_grant UNIQUE (tenant_org_id, platform_account_id),  CONSTRAINT uq_ntf_pacct_gr_tnt UNIQUE (id, tenant_org_id),  CONSTRAINT ck_ntf_pacct_gr_state CHECK (grant_state IN ('ACTIVE', 'SUSPENDED', 'REVOKED', 'EXPIRED')),  CONSTRAINT ck_ntf_pacct_gr_window CHECK (ends_at IS NULL OR ends_at > starts_at));CREATE TABLE org_ntf_plat_send_gr (  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),  tenant_org_id UUID NOT NULL,  account_grant_id UUID NOT NULL,  platform_sender_id UUID NOT NULL,  grant_state TEXT NOT NULL DEFAULT 'ACTIVE',  grant_version INTEGER NOT NULL DEFAULT 1,  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by TEXT, created_info TEXT,  updated_at TIMESTAMPTZ, updated_by TEXT, updated_info TEXT,  rec_status SMALLINT NOT NULL DEFAULT 1, rec_order INTEGER, rec_notes TEXT,  is_active BOOLEAN NOT NULL DEFAULT true,  CONSTRAINT fk_ntf_psend_gr_sender FOREIGN KEY (platform_sender_id) REFERENCES sys_ntf_prov_send_mst(id) ON DELETE RESTRICT,  CONSTRAINT fk_ntf_psend_gr_tenant FOREIGN KEY (account_grant_id, tenant_org_id) REFERENCES org_ntf_plat_acct_gr(id, tenant_org_id) ON DELETE RESTRICT,  CONSTRAINT uq_ntf_psend_grant UNIQUE (tenant_org_id, account_grant_id, platform_sender_id),  CONSTRAINT ck_ntf_psend_gr_state CHECK (grant_state IN ('ACTIVE', 'SUSPENDED', 'REVOKED')));COMMENT ON TABLE org_ntf_plat_acct_gr IS 'Tenant authorization to use a platform-owned provider account without access to its credentials.';COMMENT ON TABLE org_ntf_plat_send_gr IS 'Tenant authorization to use a sender belonging to a granted platform provider account.';COMMENT ON CONSTRAINT uq_ntf_pacct_gr_tnt ON org_ntf_plat_acct_gr IS 'Provides tenant-safe composite identity for sender-grant references.';COMMENT ON CONSTRAINT fk_ntf_psend_gr_tenant ON org_ntf_plat_send_gr IS 'Prevents a sender grant from referencing another tenant account grant.';COMMENT ON CONSTRAINT uq_ntf_psend_grant ON org_ntf_plat_send_gr IS 'Prevents duplicate tenant authorization for the same granted platform sender.';COMMENT ON CONSTRAINT ck_ntf_psend_gr_state ON org_ntf_plat_send_gr IS 'Restricts sender-grant lifecycle to explicit states.';ALTER TABLE org_ntf_plat_acct_gr ENABLE ROW LEVEL SECURITY;ALTER TABLE org_ntf_plat_send_gr ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_iso_ntf_pag_read ON org_ntf_plat_acct_gr FOR SELECT USING (tenant_org_id = current_tenant_id());CREATE POLICY tenant_iso_ntf_psg_read ON org_ntf_plat_send_gr FOR SELECT USING (tenant_org_id = current_tenant_id());COMMENT ON POLICY tenant_iso_ntf_pag_read ON org_ntf_plat_acct_gr IS 'Tenant isolation for account-grant visibility.';COMMENT ON POLICY tenant_iso_ntf_psg_read ON org_ntf_plat_send_gr IS 'Tenant isolation for sender-grant visibility.';-- Preserve legacy configuration reads. These nullable references are populated-- only through a validated activation service in the next API slice.ALTER TABLE org_ntf_channel_provider_cf  ADD COLUMN platform_account_id UUID,  ADD COLUMN private_account_id UUID,  ADD COLUMN platform_sender_id UUID,  ADD COLUMN private_sender_id UUID,  ADD COLUMN assignment_version INTEGER NOT NULL DEFAULT 1,  ADD COLUMN config_schema_rev INTEGER;ALTER TABLE org_ntf_channel_provider_cf  ADD CONSTRAINT fk_ntf_chprov_sacct FOREIGN KEY (platform_account_id) REFERENCES sys_ntf_prov_acct_mst(id) ON DELETE RESTRICT,  ADD CONSTRAINT fk_ntf_chprov_ssend FOREIGN KEY (platform_sender_id) REFERENCES sys_ntf_prov_send_mst(id) ON DELETE RESTRICT,  ADD CONSTRAINT fk_ntf_chprov_pacct FOREIGN KEY (private_account_id, tenant_org_id) REFERENCES org_ntf_prov_acct_mst(id, tenant_org_id) ON DELETE RESTRICT,  ADD CONSTRAINT fk_ntf_chprov_psend FOREIGN KEY (private_sender_id, tenant_org_id) REFERENCES org_ntf_prov_send_mst(id, tenant_org_id) ON DELETE RESTRICT,  ADD CONSTRAINT ck_ntf_chprov_acct CHECK (num_nonnulls(platform_account_id, private_account_id) <= 1),  ADD CONSTRAINT ck_ntf_chprov_send CHECK (num_nonnulls(platform_sender_id, private_sender_id) <= 1),  ADD CONSTRAINT ck_ntf_chprov_aversion CHECK (assignment_version > 0);COMMENT ON COLUMN org_ntf_channel_provider_cf.platform_account_id IS 'Optional platform account selected by the future validated assignment path.';COMMENT ON COLUMN org_ntf_channel_provider_cf.private_account_id IS 'Optional tenant account selected by the future validated assignment path.';COMMENT ON COLUMN org_ntf_channel_provider_cf.platform_sender_id IS 'Optional platform sender selected by the future validated assignment path.';COMMENT ON COLUMN org_ntf_channel_provider_cf.private_sender_id IS 'Optional tenant sender selected by the future validated assignment path.';COMMENT ON COLUMN org_ntf_channel_provider_cf.assignment_version IS 'Optimistic assignment revision incremented only by controlled activation.';COMMENT ON COLUMN org_ntf_channel_provider_cf.config_schema_rev IS 'Connector configuration schema revision used to validate legacy compatibility JSON.';COMMENT ON CONSTRAINT fk_ntf_chprov_pacct ON org_ntf_channel_provider_cf IS 'Prevents a provider configuration from selecting a tenant account owned by another tenant.';COMMENT ON CONSTRAINT fk_ntf_chprov_psend ON org_ntf_channel_provider_cf IS 'Prevents a provider configuration from selecting a tenant sender owned by another tenant.';COMMENT ON CONSTRAINT ck_ntf_chprov_acct ON org_ntf_channel_provider_cf IS 'Allows zero or one account selection during compatibility rollout; platform and tenant accounts cannot both be selected.';COMMENT ON CONSTRAINT ck_ntf_chprov_send ON org_ntf_channel_provider_cf IS 'Allows zero or one sender selection during compatibility rollout; platform and tenant senders cannot both be selected.';COMMENT ON CONSTRAINT ck_ntf_chprov_aversion ON org_ntf_channel_provider_cf IS 'Requires a positive optimistic assignment revision for safe activation.';COMMIT;